CREATE TABLE users (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),  -- a unique ID, made automatically
  username TEXT NOT NULL,                         -- NOT NULL = this can't be empty
  password_salt TEXT NOT NULL,
  password_hash TEXT NOT NULL                     -- the scrambled password, never the real one
);
CREATE UNIQUE INDEX ON users (lower(username));   -- no two people can share a username


CREATE TABLE posts (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title TEXT NOT NULL,
  content TEXT NOT NULL,
  author_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE
);
